mapper.select:
SELECT cmmn_cd AS value, /* 코드 */ cmmn_cd_nm AS name, /* 코드명 */ cd_grop_cd AS cdGroup, /* 상위 코드 */ sort_seq AS sortSn /* 정렬 순번 */ FROM cdm_own.cmmn_cd WHERE 1=1
AND cd_grop_cd = #{codeGroup}
AND use_yn = 'Y' AND lcal_cd = #{locale} ORDER BY sort_seq, cmmn_cd

SELECT cd_grop_cd AS "cdGroup", cmmn_cd AS "cd", ref_cd AS "rfrncCd", ref_vlu AS "rfrncVl" FROM cdm_own.ref_cd WHERE 1=1
AND cd_grop_cd = #{codeGroup}
AND lcal_cd = #{locale}
